#[cfg(test)]
mod tests {
    use super::*;
    use crate::icons::art::tests::assert_fits;

    #[test]
    fn every_glyph_fits_the_view_box() {
        for (art, name) in [
            (&HEADPHONES_02, "HEADPHONES_02"),
            (&LAPTOP_01, "LAPTOP_01"),
            (&MONITOR_01, "MONITOR_01"),
            (&KEYBOARD_01, "KEYBOARD_01"),
            (&PHONE_01, "PHONE_01"),
            (&MICROPHONE_02, "MICROPHONE_02"),
            (&SUN, "SUN"),
            (&MOON_01, "MOON_01"),
            (&ALERT_TRIANGLE, "ALERT_TRIANGLE"),
            (&GAUGE_LOW, "GAUGE_LOW"),
            (&GAUGE_MID, "GAUGE_MID"),
            (&GAUGE_HIGH, "GAUGE_HIGH"),
            (&BROWSER, "BROWSER"),
            (&GRID_01, "GRID_01"),
            (&MAGIC_WAND_02, "MAGIC_WAND_02"),
            (&CLOCK_STOPWATCH, "CLOCK_STOPWATCH"),
            (&HOURGLASS_01, "HOURGLASS_01"),
            (&MUSIC_NOTE_01, "MUSIC_NOTE_01"),
            (&TERMINAL_SQUARE, "TERMINAL_SQUARE"),
            (&ARROW_SQUARE_DOWN, "ARROW_SQUARE_DOWN"),
            (&CHECK_CIRCLE, "CHECK_CIRCLE"),
            (&X_CIRCLE, "X_CIRCLE"),
            (&MESSAGE_QUESTION_SQUARE, "MESSAGE_QUESTION_SQUARE"),
            (&VIDEO_RECORDER, "VIDEO_RECORDER"),
            (&REFRESH_CW_01, "REFRESH_CW_01"),
            (&PHONE_CALL_01, "PHONE_CALL_01"),
            (&WEBCAM_01, "WEBCAM_01"),
            (&MONITOR_05, "MONITOR_05"),
            (&VOLUME_MAX, "VOLUME_MAX"),
            (&WIFI, "WIFI"),
            (&BLUETOOTH_ON, "BLUETOOTH_ON"),
            (&COFFEE, "COFFEE"),
        ] {
            assert_fits(art, name);
        }
    }
}
